package com.obysoft.faithOS.entity;
import java.time.LocalDateTime;import jakarta.persistence.*;
@Entity @Table(name="attendance_devices") public class AttendanceDevice{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JoinColumn(name="church_id")private Church church;@Column(name="device_id",nullable=false,unique=true,length=80)private String deviceId;@Column(nullable=false,length=120)private String name;@Column(name="secret_hash",nullable=false,length=100)private String secretHash;@Column(nullable=false)private boolean active=true;@Column(name="failed_attempts",nullable=false)private int failedAttempts;@Column(name="locked_until")private LocalDateTime lockedUntil;@Column(name="last_used_at")private LocalDateTime lastUsedAt;@Column(name="created_at",nullable=false,updatable=false)private LocalDateTime createdAt;@PrePersist void created(){createdAt=LocalDateTime.now();}public Long getId(){return id;}public Church getChurch(){return church;}public void setChurch(Church v){church=v;}public String getDeviceId(){return deviceId;}public void setDeviceId(String v){deviceId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getSecretHash(){return secretHash;}public void setSecretHash(String v){secretHash=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public int getFailedAttempts(){return failedAttempts;}public void setFailedAttempts(int v){failedAttempts=v;}public LocalDateTime getLockedUntil(){return lockedUntil;}public void setLockedUntil(LocalDateTime v){lockedUntil=v;}public LocalDateTime getLastUsedAt(){return lastUsedAt;}public void setLastUsedAt(LocalDateTime v){lastUsedAt=v;}}
